# CUDA kernel: batched half‑precision GEMM using Tensor Cores (WMMA)
# ------------------------------------------------------------
cuda_source = r"""
#include <torch/extension.h>
#include <cuda_runtime.h>
#include <cuda_fp16.h>
#include <mma.h>

using namespace nvcuda;

// Tile size for each thread block (128 x 128 output)
#define WMMA_M 16
#define WMMA_N 16
#define WMMA_K 16
#define BLOCK_M 128   // rows per CTA
#define BLOCK_N 128   // cols per CTA
#define BLOCK_K 16    // depth per tile load

// Shared memory layout: A tile (BLOCK_M x BLOCK_K) + B tile (BLOCK_K x BLOCK_N)
extern __shared__ __half shmem[];

#define SHMEM_A (shmem)                                            // size BLOCK_M * BLOCK_K
#define SHMEM_B (shmem + BLOCK_M * BLOCK_K)                        // size BLOCK_K * BLOCK_N

// ------------------------------------------------------------
__global__ void bmm_wmma_kernel(const __half* __restrict__ A,
                                 const __half* __restrict__ B,
                                 __half* __restrict__ C,
                                 int batch,
                                 int M, int N, int K) {
    // --------------------------------------------------------
    // block / grid indices
    // --------------------------------------------------------
    int b = blockIdx.z;                     // batch dimension
    if (b >= batch) return;

    int block_row = blockIdx.y;             // which 128‑row tile
    int block_col = blockIdx.x;             // which 128‑col tile

    // starting coordinates of the tile in the output matrix
    int row_base = block_row * BLOCK_M;
    int col_base = block_col * BLOCK_N;

    // pointers to the current batch
    const __half* A_batch = A + (size_t)b * M * K;
    const __half* B_batch = B + (size_t)b * K * N;
    __half*       C_batch = C + (size_t)b * M * N;

    // --------------------------------------------------------
    // each warp will compute one 16x16 WMMA tile inside the 128x128 CTA
    // --------------------------------------------------------
    const int warp_id   = threadIdx.x / 32;          // 0..7  (since 256 threads per CTA)
    const int lane_id   = threadIdx.x % 32;

    // coordinates of the WMMA tile this warp computes
    const int warp_tile_row = (warp_id / 8) * WMMA_M;   // 0,16,32,48,64,80,96,112
    const int warp_tile_col = (warp_id % 8) * WMMA_N;

    // fragment declarations
    wmma::fragment<wmma::matrix_a, WMMA_M, WMMA_N, WMMA_K, __half, wmma::row_major> a_frag;
    wmma::fragment<wmma::matrix_b, WMMA_M, WMMA_N, WMMA_K, __half, wmma::row_major> b_frag;
    wmma::fragment<wmma::accumulator, WMMA_M, WMMA_N, WMMA_K, float>          c_frag;

    wmma::fill_fragment(c_frag, 0.0f);

    // --------------------------------------------------------
    // loop over K dimension in BLOCK_K steps (16)
    // --------------------------------------------------------
    for (int kb = 0; kb < K; kb += BLOCK_K) {
        // ----------------------------------------------------
        // Load A tile (BLOCK_M x BLOCK_K) into shared memory
        // ----------------------------------------------------
        // Each thread loads 8 elements (since 256 threads * 8 = 2048 = BLOCK_M*BLOCK_K)
        for (int i = threadIdx.x; i < BLOCK_M * BLOCK_K; i += blockDim.x) {
            int a_row = i / BLOCK_K;
            int a_col = i % BLOCK_K;
            int g_row = row_base + a_row;
            int g_col = kb + a_col;
            SHMEM_A[a_row * BLOCK_K + a_col] = A_batch[g_row * K + g_col];
        }

        // ----------------------------------------------------
        // Load B tile (BLOCK_K x BLOCK_N) into shared memory
        // ----------------------------------------------------
        for (int i = threadIdx.x; i < BLOCK_K * BLOCK_N; i += blockDim.x) {
            int b_row = i / BLOCK_N;
            int b_col = i % BLOCK_N;
            int g_row = kb + b_row;
            int g_col = col_base + b_col;
            SHMEM_B[b_row * BLOCK_N + b_col] = B_batch[g_row * N + g_col];
        }

        __syncthreads();

        // ----------------------------------------------------
        // Load fragments for this warp
        // ----------------------------------------------------
        // A fragment: rows = warp_tile_row .. warp_tile_row+15, cols = 0..15 of shared A
        const __half* a_tile_ptr = SHMEM_A + warp_tile_row * BLOCK_K;
        wmma::load_matrix_sync(a_frag, a_tile_ptr, BLOCK_K);

        // B fragment: rows = 0..15, cols = warp_tile_col .. warp_tile_col+15 of shared B
        const __half* b_tile_ptr = SHMEM_B + warp_tile_col;
        wmma::load_matrix_sync(b_frag, b_tile_ptr, BLOCK_N);

        // ----------------------------------------------------
        // WMMA matrix multiply-accumulate
        // ----------------------------------------------------
        wmma::mma_sync(c_frag, a_frag, b_frag, c_frag);

        __syncthreads();   // ensure shared memory not overwritten before next kb
    }

    // ----------------------------------------------------
    // Store the result tile to global memory
    // ----------------------------------------------------
    __half* c_tile_ptr = C_batch + (row_base + warp_tile_row) * N + (col_base + warp_tile_col);
    wmma::store_matrix_sync(c_tile_ptr, c_frag, N, wmma::mem_row_major);
}

// ------------------------------------------------------------
// Host wrapper
// ------------------------------------------------------------
torch::Tensor bmm_cuda(torch::Tensor A, torch::Tensor B) {
    TORCH_CHECK(A.dtype() == torch::kFloat16, "A must be float16");
    TORCH_CHECK(B.dtype() == torch::kFloat16, "B must be float16");
    TORCH_CHECK(A.is_cuda() && B.is_cuda(), "inputs must be CUDA tensors");
    TORCH_CHECK(A.dim() == 3 && B.dim() == 3, "inputs must be 3‑D tensors");
    TORCH_CHECK(A.size(0) == B.size(0), "batch dimensions must match");
    TORCH_CHECK(A.size(2) == B.size(1), "inner dimensions must match");

    const int64_t batch = A.size(0);
    const int64_t M = A.size(1);
    const int64_t K = A.size(2);
    const int64_t N = B.size(2);

    // Assuming dimensions are multiples of BLOCK_M/N and WMMA_K (true for the provided test)
    auto C = torch::empty({batch, M, N}, A.options());

    dim3 block(256);                                     // 256 threads per CTA
    dim3 grid((N + BLOCK_N - 1) / BLOCK_N,
              (M + BLOCK_M - 1) / BLOCK_M,
              static_cast<unsigned int>(batch));

    size_t shmem_bytes = (BLOCK_M * BLOCK_K + BLOCK_K * BLOCK_N) * sizeof(__half);
    bmm_wmma_kernel<<<grid, block, shmem_bytes>>>(
        reinterpret_cast<const __half*>(A.data_ptr<at::Half>()),
        reinterpret_cast<const __half*>(B.data_ptr<at::Half>()),
        reinterpret_cast<__half*>(C.data_ptr<at::Half>()),
        static_cast<int>(batch),
        static_cast<int>(M),
        static_cast<int>(N),
        static_cast<int>(K));

    cudaError_t err = cudaGetLastError();
    if (err != cudaSuccess) {
        AT_ERROR("CUDA kernel launch failed: ", cudaGetErrorString(err));
    }
    return C;
}
"""

